  console.error('STEP nego kex='+kex+' enc='+enc+' mac='+mac);

  const eph=crypto.generateKeyPairSync('x25519');
  const qcRaw=Buffer.from(eph.publicKey.export({format:'jwk'}).x,'base64url');
  ssh.sendRaw(Buffer.concat([Buffer.from([30]), s(qcRaw)]));
  console.error('STEP sent ECDH_INIT');
  const reply=await ssh.readPacket();
  console.error('STEP got reply type='+reply.type+' len='+reply.payload.length);
  if(reply.type===1) throw new Error('DISCONNECT reason='+reply.payload.readUInt32BE(1)+' msg='+parseStr(reply.payload,5).v.toString());
  if(reply.type"'!==31) throw new Error('"'expected 31 got '+reply.type);
  const ks=parseStr(reply.payload,1); const qs=parseStr(reply.payload,ks.off); const sigblob=parseStr(reply.payload,qs.off);
  const serverPub=crypto.createPublicKey({key:{kty:'OKP',crv:'X25519',x:qs.v.toString('base64url')},format:'jwk'});
  const K=mpint(crypto.diffieHellman({privateKey:eph.privateKey,publicKey:serverPub}));
  const H=sha256(Buffer.from(V_C,'latin1'),Buffer.from(V_S,'latin1'),myKex,sk.payload,ks.v,s(qcRaw),s(qs.v),K);
  const expectedHostBlob=Buffer.concat([s('ssh-ed25519'),s(hostRaw)]);
  if("'!ks.v.equals(expectedHostBlob)) throw new Error('"'HOST KEY MISMATCH');
  const sig=parseStr(sigblob.v,0); const sigRaw=parseStr(sigblob.v,sig.off);
  if(sig.v.toString()"'!=='"'ssh-ed25519') throw new Error('sig algo '+sig.v);
  if("'!crypto.verify(null,H,hostPub,sigRaw.v)) throw new Error('"'host signature FAILED');
  console.error('STEP hostkey verified fp=SHA256:'+Buffer.from(sha256(hostRaw)).toString('base64'));
  ssh.sendRaw(Buffer.from([21]));
  await ssh.readType(21);
  console.error('STEP NEWKEYS ok');

  const keyLen=enc==='aes256-ctr'?32:enc==='aes192-ctr'?24:16;
  const macLen=mac==='hmac-sha2-512'?64:32;
  const deriveKey=(ch)=>sha256(K,H,Buffer.from([ch]),H);
  ssh.encOut={key:deriveKey(0x43).subarray(0,keyLen),iv:deriveKey(0x41).subarray(0,16)};
  ssh.encIn={key:deriveKey(0x44).subarray(0,keyLen),iv:deriveKey(0x42).subarray(0,16)};
  ssh.macOut={key:deriveKey(0x45).subarray(0,macLen)};
  ssh.macIn={key:deriveKey(0x46).subarray(0,macLen)};

  ssh.sendRaw(Buffer.concat([Buffer.from([5]),s('ssh-userauth')]));
  await ssh.readType(6);
  console.error('STEP SERVICE_ACCEPT');

  function buildPkReq(signedFlag, sigBuf){
    const parts=[Buffer.from([50]),s(USER),s('ssh-connection'),s('publickey'),bool(signedFlag),s('ssh-ed25519'),s(clientPubBlob)];
    if(signedFlag) parts.push(s(sigBuf));
    return Buffer.concat(parts);
  }
  ssh.sendRaw(buildPkReq(false));
  await ssh.readType(60);
  console.error('STEP PK_OK');
  const payloadNoSig=Buffer.concat([Buffer.from([50]),s(USER),s('ssh-connection'),s('publickey'),bool(true),s('ssh-ed25519'),s(clientPubBlob)]);
  const rawSig=crypto.sign(null,Buffer.concat([H,payloadNoSig]),clientPriv);
  ssh.sendRaw(buildPkReq(true,Buffer.concat([s('ssh-ed25519'),s(rawSig)])));
  await ssh.readType(52);
  console.error('STEP AUTH_OK');

  ssh.sendRaw(Buffer.concat([Buffer.from([90]),s('session'),uint32(0),uint32(1048576),uint32(32768)]));
  const conf=await ssh.readType(91);
  const serverChan=conf.payload.readUInt32BE(5);
  ssh.sendRaw(Buffer.concat([Buffer.from([98]),uint32(serverChan),s('exec'),bool(true),s(cmd)]));
  const sr=await ssh.readPacket();
  if(sr.type===100) throw new Error('exec request failed');
  if(sr.type"'!==99) throw new Error('"'unexpected type after exec '+sr.type);

  let out='', err='', exit=null;
  while(true){
    const pkt=await ssh.readPacket();
    if(pkt.type===94){ const r=parseStr(pkt.payload,5); out+=r.v.toString('utf8'); ssh.sendRaw(Buffer.concat([Buffer.from([93]),uint32(serverChan),uint32(r.v.length)])); }
    else if(pkt.type===95){ const r=parseStr(pkt.payload,9); err+=r.v.toString('utf8'); ssh.sendRaw(Buffer.concat([Buffer.from([93]),uint32(serverChan),uint32(r.v.length)])); }
    else if(pkt.type===97){ break; }
    else if(pkt.type===98){ const nm=parseStr(pkt.payload,4); if(nm.v.toString()==='exit-status') exit=pkt.payload.readUInt32BE(nm.off+1); }
  }
  ssh.sendRaw(Buffer.concat([Buffer.from([97]),uint32(serverChan)]));
  console.log('=== STDOUT ===');
  process.stdout.write(out);
  if(err){ console.log('=== STDERR ==='); process.stdout.write(err); }
  console.log('=== EXIT '+(exit===null?'null':exit)+' ===');
  sock.end();
  process.exit(exit===null?0:exit);
}
main().catch(e=>{ console.error('SSH_FAIL: '+e.stack); process.exit(3); });
